path":"pct_prev","gt":0}]},{"section":"D","path":"prev_diag.shared_freq","label":"Exam shared frequency","type":"boolean","when":[{"path":"pct_prev","gt":0}]},{"section":"D","path":"prev_diag.tx_with_limited","label":"Treatment with limited exam","type":"boolean","when":[{"path":"pct_prev","gt":0}]},{"section":"D","path":"prev_diag.fmx_pano_shared","label":"FMX / pano shared frequency","type":"boolean","when":[{"path":"pct_prev","gt":0}]},{"section":"D","path":"prev_diag.eligible_fmx_pano","label":"Eligible for FMX / pano","type":"boolean","when":[{"path":"pct_prev","gt":0}]},{"section":"E","path":"restorative.post_comp_pct","label":"Posterior composite coverage","type":"number","max":100},{"section":"E","path":"restorative.post_comp_freq","label":"Posterior composite frequency","type":"text","when":[{"path":"restorative.post_comp_pct","gt":0}]},{"section":"E","path":"restorative.post_comp_downgraded","label":"Posterior composite downgraded","type":"boolean","when":[{"path":"restorative.post_comp_pct","gt":0}]},{"section":"E","path":"restorative.post_comp_downgrade_codes","label":"Posterior composite downgrade codes","type":"text","when":[{"path":"restorative.post_comp_downgraded","eq":true}],"identity":true},{"section":"E","path":"restorative.porc_crown_pct","label":"Porcelain crown coverage","type":"number","max":100},{"section":"E","path":"restorative.porc_crown_freq","label":"Porcelain crown frequency","type":"text","when":[{"path":"restorative.porc_crown_pct","gt":0}]},{"section":"E","path":"restorative.porc_crown_downgrade","label":"Porcelain crown downgraded","type":"boolean","when":[{"path":"restorative.porc_crown_pct","gt":0}]},{"section":"E","path":"restorative.porc_crown_downgrade_code","label":"Porcelain crown downgrade codes","type":"text","when":[{"path":"restorative.porc_crown_downgrade","eq":true}],"identity":true},{"section":"E","path":"restorative.onlay_pct","label":"Onlay coverage","type":"number","max":100},{"section":"E","path":"restorative.onlay_freq","label":"Onlay frequency","type":"text","when":[{"path":"restorative.onlay_pct","gt":0}]},{"section":"E","path":"restorative.onlay_downgrade","label":"Onlay downgraded","type":"boolean","when":[{"path":"restorative.onlay_pct","gt":0}]},{"section":"E","path":"restorative.onlay_downgrade_code","label":"Onlay downgrade codes","type":"text","when":[{"path":"restorative.onlay_downgrade","eq":true}],"identity":true},{"section":"E","path":"restorative.crowns_paid_on","label":"Crowns paid on","type":"enum","options":["Prep Date","Seat Date"],"when":[{"path":"restorative.porc_crown_pct","gt":0}]},{"section":"E","path":"restorative.bridges_dentures_pct","label":"Bridges / dentures coverage","type":"number","max":100},{"section":"E","path":"restorative.bridges_dentures_freq","label":"Bridges / dentures frequency","type":"text","when":[{"path":"restorative.bridges_dentures_pct","gt":0}]},{"section":"F","path":"periodontics.srp_pct","label":"SRP coverage","type":"number","max":100},{"section":"F","path":"periodontics.srp_freq","label":"SRP frequency","type":"text","when":[{"path":"periodontics.srp_pct","gt":0}]},{"section":"F","path":"periodontics.perio_maint_pct","label":"Periodontal maintenance coverage","type":"number","max":100},{"section":"F","path":"periodontics.perio_maint_freq","label":"Periodontal maintenance frequency","type":"text","when":[{"path":"periodontics.perio_maint_pct","gt":0}]},{"section":"F","path":"periodontics.debridement_pct","label":"Debridement coverage","type":"number","max":100},{"section":"F","path":"periodontics.debridement_freq","label":"Debridement frequency","type":"text","when":[{"path":"periodontics.debridement_pct","gt":0}]},{"section":"F","path":"periodontics.crown_lengthening_pct","label":"Crown lengthening coverage","type":"number","max":100},{"section":"F","path":"periodontics.crown_lengthening_freq","label":"Crown lengthening frequency","type":"text","when":[{"path":"periodontics.crown_lengthening_pct","gt":0}]},{"section":"F","path":"periodontics.osseous_pct","label":"Osseous surgery coverage","type":"number","max":100},{"section":"F","path":"periodontics.osseous_freq","label":"Osseous surgery frequency","type":"text","when":[{"path":"periodontics.osseous_pct","gt":0}]},{"section":"F","path":"periodontics.tissue_graft_pct","label":"Tissue graft coverage","type":"number","max":100},{"section":"F","path":"periodontics.tissue_graft_freq","label":"Tissue graft frequency","type":"text","when":[{"path":"periodontics.tissue_graft_pct","gt":0}]},{"section":"F","path":"periodontics.arestin_pct","label":"Arestin coverage","type":"number","max":100},{"section":"F","path":"periodontics.arestin_freq","label":"Arestin frequency","type":"text","when":[{"path":"periodontics.arestin_pct","gt":0}]},{"section":"F","path":"periodontics.srp_quads","label":"SRP quadrants allowed","type":"text","when":[{"path":"periodontics.srp_pct","gt":0}]},{"section":"F","path":"periodontics.healing_period_srp_pmr","label":"Healing period between SRP and maintenance","type":"text","when":[{"path":"periodontics.perio_maint_pct","gt":0}]},{"section":"F","path":"periodontics.perio_maint_shared_prophy","label":"Maintenance shares prophy frequency","type":"boolean","when":[{"path":"periodontics.perio_maint_pct","gt":0}]},{"section":"G","path":"oral_surgery.os_to_medical_primary","label":"Oral surgery medical primary","type":"boolean"},{"section":"G","path":"oral_surgery.d7210_pct","label":"D7210 coverage","type":"number","max":100},{"section":"G","path":"oral_surgery.d7220_pct","label":"D7220 coverage","type":"number","max":100},{"section":"G","path":"oral_surgery.d7230_pct","label":"D7230 coverage","type":"number","max":100},{"section":"G","path":"oral_surgery.d7240_pct","label":"D7240 coverage","type":"number","max":100},{"section":"G","path":"oral_surgery.d7241_pct","label":"D7241 coverage","type":"number","max":100},{"section":"G","path":"oral_surgery.d7250_pct","label":"D7250 coverage","type":"number","max":100},{"section":"G","path":"oral_surgery.d7251_pct","label":"D7251 coverage","type":"number","max":100},{"section":"G","path":"oral_surgery.bone_graft_pct","label":"Bone graft coverage","type":"number","max":100},{"section":"G","path":"oral_surgery.bone_graft_freq","label":"Bone graft frequency","type":"text","when":[{"path":"oral_surgery.bone_graft_pct","gt":0}]},{"section":"G","path":"oral_surgery.bone_graft_implant_pct","label":"Bone graft for implant coverage","type":"number","max":100},{"section":"G","path":"oral_surgery.bone_graft_implant_freq","label":"Bone graft for implant frequency","type":"text","when":[{"path":"oral_surgery.bone_graft_implant_pct","gt":0}]},{"section":"G","path":"oral_surgery.gtr_pct","label":"GTR coverage","type":"number","max":100},{"section":"G","path":"oral_surgery.gtr_freq","label":"GTR frequency","type":"text","when":[{"path":"oral_surgery.gtr_pct","gt":0}]},{"section":"G","path":"oral_surgery.gtr_implant_pct","label":"GTR for implant coverage","type":"number","max":100},{"section":"G","path":"oral_surgery.gtr_implant_freq","label":"GTR for implant frequency","type":"text","when":[{"path":"oral_surgery.gtr_implant_pct","gt":0}]},{"section":"G","path":"oral_surgery.incision_drainage_pct","label":"Incision / drainage coverage","type":"number","max":100},{"section":"G","path":"oral_surgery.incision_drainage_freq","label":"Incision / drainage frequency","type":"text","when":[{"path":"oral_surgery.incision_drainage_pct","gt":0}]},{"section":"H","path":"implants.implant_body_pct","label":"Implant body coverage","type":"number","max":100},{"section":"H","path":"implants.implant_abutment_pct","label":"Implant abutment coverage","type":"number","max":100},{"section":"H","path":"implants.implant_crown_pct","label":"Implant crown coverage","type":"number","max":100},{"section":"H","path":"implants.porc_pontic_pct","label":"Porcelain pontic coverage","type":"number","max":100},{"section":"H","path":"implants.abutment_retainer_pct","label":"Abutment retainer coverage","type":"number","max":100},{"section":"H","path":"implants.implant_freq","label":"Implant frequency","type":"text","when":[{"path":"implants.implant_body_pct","gt":0},{"path":"implants.implant_abutment_pct","gt":0},{"path":"implants.implant_crown_pct","gt":0}]},{"section":"H","path":"implants.implant_downgrade","label":"Implant downgrade","type":"text","when":[{"path":"implants.implant_body_pct","gt":0},{"path":"implants.implant_abutment_pct","gt":0},{"path":"implants.implant_crown_pct","gt":0}]},{"section":"H","path":"implants.abutment_downgrade","label":"Abutment downgrade","type":"text","when":[{"path":"implants.porc_pontic_pct","gt":0},{"path":"implants.abutment_retainer_pct","gt":0}]},{"section":"I","path":"ortho.ortho_pct","label":"Orthodontic coverage","type":"number","max":100},{"section":"I","path":"ortho.ortho_max","label":"Orthodontic maximum","type":"number","allowNA":true,"when":[{"path":"ortho.ortho_pct","gt":0}]},{"section":"I","path":"ortho.ortho_age_limit","label":"Orthodontic age limit","type":"text","when":[{"path":"ortho.ortho_pct","gt":0}]},{"section":"I","path":"ortho.ortho_deductible","label":"Orthodontic deductible applies","type":"boolean","when":[{"path":"ortho.ortho_pct","gt":0}]},{"section":"J","path":"misc.consult_pct","label":"Consultation coverage","type":"number","max":100},{"section":"J","path":"misc.consult_freq","label":"Consultation frequency","type":"text","when":[{"path":"misc.consult_pct","gt":0}]},{"section":"J","path":"misc.nitrous_pct","label":"Nitrous coverage","type":"number","max":100},{"section":"J","path":"misc.nitrous_freq","label":"Nitrous frequency","type":"text","when":[{"path":"misc.nitrous_pct","gt":0}]},{"section":"J","path":"misc.nightguard_pct","label":"Nightguard coverage","type":"number","max":100},{"section":"J","path":"misc.nightguard_freq","label":"Nightguard frequency","type":"text","when":[{"path":"misc.nightguard_pct","gt":0}]},{"section":"J","path":"misc.bruxism_or_osseous","label":"Nightguard condition: bruxism or osseous","type":"text","when":[{"path":"misc.nightguard_pct","gt":0}]},{"section":"J","path":"history.has_history","label":"Prior insurance history","type":"boolean"},{"section":"J","path":"history.history_notes","label":"Prior insurance history details","type":"text","when":[{"path":"history.has_history","eq":true}],"identity":true},{"section":"J","path":"rep_name","label":"Representative / verification source","type":"text","identity":true},{"section":"J","path":"ref_number","label":"Reference / confirmation number","type":"text","identity":true},{"section":"J","path":"employee_initials","label":"Verifier initials","type":"text","identity":true},{"section":"A","label":"Patient relationship to subscriber","type":"enum","options":["Self","Spouse","Child","Other"],"path":"form_data.subscriber_relationship"},{"section":"B","label":"Insurance order","type":"enum","options":["Primary","Secondary","Tertiary"],"path":"form_data.coverage_order"},{"section":"B","label":"Carrier-confirmed coverage status","type":"enum","options":["Active","Terminated","Not yet effective"],"path":"form_data.coverage_status"},{"section":"B","label":"Benefit renewal month","type":"enum","options":["January","February","March","April","May","June","July","August","September","October","November","December"],"path":"form_data.renewal_month"},{"section":"B","label":"Carrier-confirmed plan type","type":"enum","options":["PPO","DHMO","EPO / in-network only","Indemnity","Other"],"path":"form_data.plan_type"},{"section":"B","label":"Office fee schedule mapping","type":"enum","options":["Confirmed with office","Office review needed"],"path":"form_data.ascend_fee_schedule_status"},{"section":"B","label":"Exact Ascend fee schedule for this office","type":"text","placeholder":"Copy the exact office-specific name. Do not select a schedule solely because it says PPO.","when":[{"path":"form_data.ascend_fee_schedule_status","eq":"Confirmed with office"}],"path":"form_data.ascend_fee_schedule_name"},{"section":"B","label":"Fee schedule confirmed by","type":"text","placeholder":"Office manager or authorized reviewer and confirmation date","when":[{"path":"form_data.ascend_fee_schedule_status","eq":"Confirmed with office"}],"path":"form_data.ascend_fee_schedule_confirmed_by"},{"section":"B","label":"How were these benefits verified?","type":"enum","options":["Carrier portal","Carrier representative","Plan benefit document","Other"],"path":"form_data.carrier_verification_source"},{"section":"B","label":"Carrier evidence and unresolved questions","type":"text","multiline":true,"placeholder":"Record the verification date, portal/document reference or representative and call reference. List unanswered questions. Keep evidence in the secure request; do not paste passwords or sign-in links.","path":"form_data.carrier_evidence_reference"},{"section":"C","label":"Dependent age answer","type":"enum","options":["Age limit applies","No age limit confirmed","Not available"],"path":"form_data.dependent_age_status"},{"section":"C","label":"Student age answer","type":"enum","options":["Age limit applies","No age limit confirmed","Not available"],"path":"form_data.student_age_status"},{"section":"C","label":"Family deductible remaining ($)","type":"number","path":"form_data.family_deductible_remaining"},{"section":"C","label":"How the deductible is applied","type":"enum","options":["Combined across covered categories","Separate by category","No deductible"],"path":"form_data.deductible_structure"},{"section":"C","label":"Separate deductible amounts and balances","type":"text","multiline":true,"placeholder":"For each category, record individual and family deductible amounts and the amounts remaining. Record unavailable details as NA.","when":[{"path":"form_data.deductible_structure","eq":"Separate by category"}],"path":"form_data.deductible_details"},{"section":"D","label":"Frequency and age-limit details","type":"text","multiline":true,"placeholder":"For each procedure, confirm calendar year, plan year or rolling months; per tooth, quadrant, arch or patient; shared codes; inclusive age; lifetime limits; and exact original-to-downgrade code pairs. Example: 1 F 36M means one per 36 rolling months. Enter NA for anything the carrier cannot confirm.","path":"form_data.frequency_limit_details"},{"section":"G","label":"Office code D7953.1 coverage","type":"enum","options":["Not covered","Covered separately","Office / carrier review needed"],"path":"form_data.local_d7953_1_status"},{"section":"G","label":"Confirmed carrier code for D7953.1","type":"text","placeholder":"Exact carrier-recognized code; never assume D7953 covers a local decimal code.","when":[{"path":"form_data.local_d7953_1_status","eq":"Covered separately"}],"path":"form_data.local_d7953_1_carrier_code"},{"section":"G","label":"D7953.1 confirmed coverage (%)","type":"number","max":100,"when":[{"path":"form_data.local_d7953_1_status","eq":"Covered separately"}],"path":"form_data.local_d7953_1_pct"},{"section":"G","label":"D7953.1 frequency and confirmation reference","type":"text","multiline":true,"placeholder":"Record the limit, treatment-area scope and who confirmed the office-code mapping. NA is accepted when unavailable.","when":[{"path":"form_data.local_d7953_1_status","eq":"Covered separately"}],"path":"form_data.local_d7953_1_frequency"}]$rules$::jsonb;
  rule jsonb; condition jsonb; value jsonb; raw text; explanation text; applies boolean; valid boolean;
  errors jsonb := '[]'::jsonb;
begin
  for rule in select * from jsonb_array_elements(rules) loop
    applies := not (rule ? 'when');
    if not applies then
      for condition in select * from jsonb_array_elements(rule->'when') loop
        value := data #> string_to_array(condition->>'path','.');
        raw := regexp_replace(coalesce(value #>> '{}',''),'^[[:space:]]+|[[:space:]]+$','','g');
        if condition ? 'eq' then
          applies := applies or coalesce(value = condition->'eq',false);
        elsif raw ~ '^[0-9]+(\.[0-9]+)?$' then
          applies := applies or raw::numeric > (condition->>'gt')::numeric;
        end if;
      end loop;
    end if;
    if not applies then continue; end if;
    value := data #> string_to_array(rule->>'path','.');
    raw := regexp_replace(coalesce(value #>> '{}',''),'^[[:space:]]+|[[:space:]]+$','','g');
    explanation := regexp_replace(coalesce(data->'form_data'->'not_applicable'->>(rule->>'path'),''),'^[[:space:]]+|[[:space:]]+$','','g');
    if raw='' and jsonb_typeof(data->'form_data'->'not_applicable'->(rule->>'path'))='string' and length(explanation)>0 then continue; end if;
    valid := raw<>'';
    if valid then
      case rule->>'type'
        when 'text' then valid := jsonb_typeof(value)='string';
        when 'boolean' then valid := jsonb_typeof(value)='boolean';
        when 'enum' then valid := (rule->'options') @> jsonb_build_array(value);
        when 'checkboxes' then valid := value->'preventive'='true'::jsonb or value->'basic'='true'::jsonb or value->'major'='true'::jsonb;
        when 'number' then
          valid := jsonb_typeof(value) in ('number','string') and raw ~ '^[0-9]+(\.[0-9]+)?$';
          if valid then valid := raw::numeric>=coalesce((rule->>'min')::numeric,0) and (not (rule ? 'max') or raw::numeric<=(rule->>'max')::numeric)
            and (not coalesce((rule->>'integer')::boolean,false) or trunc(raw::numeric)=raw::numeric); end if;
        when 'date' then
          valid := jsonb_typeof(value)='string' and raw ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$';
          if valid then begin valid := to_char(raw::date,'YYYY-MM-DD')=raw; exception when others then valid:=false; end; end if;
        else valid := false;
      end case;
    end if;
    if not coalesce(valid,false) then errors := errors || jsonb_build_array(jsonb_build_object('path',rule->>'path','label',rule->>'label','section',rule->>'section')); end if;
  end loop;
  if coalesce(data->>'remaining_max','') ~ '^[0-9]+(\.[0-9]+)?$' and coalesce(data->>'yearly_max','') ~ '^[0-9]+(\.[0-9]+)?$' then
    if (data->>'remaining_max')::numeric>(data->>'yearly_max')::numeric then errors:=errors||jsonb_build_array(jsonb_build_object('path','remaining_max','label','Remaining maximum cannot exceed yearly maximum','section','C')); end if;
  end if;
  if coalesce(data->>'individual_deductible_remaining','') ~ '^[0-9]+(\.[0-9]+)?$' and coalesce(data->>'deductible','') ~ '^[0-9]+(\.[0-9]+)?$' then
    if (data->>'individual_deductible_remaining')::numeric>(data->>'deductible')::numeric then errors:=errors||jsonb_build_array(jsonb_build_object('path','individual_deductible_remaining','label','Remaining deductible cannot exceed the deductible','section','C')); end if;
  end if;
  if coalesce(data->>'term_date','')<>'' and coalesce(data->>'eff_date','')<>'' and data->>'term_date'<data->>'eff_date' then
    errors:=errors||jsonb_build_array(jsonb_build_object('path','term_date','label','Term date cannot precede effective date','section','B'));
  end if;
  if coalesce(data->'form_data'->>'family_deductible_remaining','') ~ '^[0-9]+(\.[0-9]+)?$' and coalesce(data->>'family_deductible','') ~ '^[0-9]+(\.[0-9]+)?$' then
    if (data->'form_data'->>'family_deductible_remaining')::numeric>(data->>'family_deductible')::numeric then errors:=errors||jsonb_build_array(jsonb_build_object('path','form_data.family_deductible_remaining','label','Remaining family deductible cannot exceed the family deductible','section','C')); end if;
  end if;
  return errors;
end; $fn$;
revoke all on function insurance_internal.completion_errors(jsonb) from public, anon;
grant execute on function insurance_internal.completion_errors(jsonb) to authenticated, service_role;

create or replace function insurance_internal.plan_review_alert() returns trigger
language plpgsql security definer set search_path='' as $$
declare office uuid; label text; attached boolean; alert_title text; alert_message text;
begin
  select r.office_id,o.name into office,label from public.insurance_verification_requests r
    join public.offices o on o.id=r.office_id where r.id=new.request_id;
  if new.state='needs_review' then
    attached := new.patient_id is not null and new.plan_id is not null
      and new.receipt @> '{"patient":true,"office":true,"carrier":true,"payer":true,"group":true,"subscriber":true,"relationship":true,"order":true,"effective_date":true,"reopened":true}'::jsonb;
    alert_title := case when attached then 'Insurance plan attached — benefit review needed' else 'Insurance plan entry needs review' end;
    alert_message := label || case when attached
      then ': The native insurance plan is already attached. Review the remaining benefits and restrictions with Patricia and the office manager in the request discrepancy log. Do not attach a duplicate policy. PDF filing is separate.'
      else ': The insurance plan could not be safely entered in Ascend. Open the completed breakdown and confirm the patient, subscriber and exact group plan with Patricia. PDF filing is separate.' end;
    update public.notifications set title=alert_title,message=alert_message,
      metadata=metadata||jsonb_build_object('reason_codes',new.reason_codes,'plan_attached_verified',attached)
      where metadata->>'plan_entry_verification_id'=new.verification_id::text and not coalesce(is_archived,false);
    insert into public.notifications(user_id,office_id,notification_type,title,message,metadata)
      select r.user_id,office,'insurance_needs_review',alert_title,alert_message,
        jsonb_build_object('request_id',new.request_id,'plan_entry_verification_id',new.verification_id,'reason_codes',new.reason_codes,'plan_attached_verified',attached,'priority','high')
      from insurance_internal.review_recipients(office) r
      where not exists(select 1 from public.notifications n where n.user_id=r.user_id
        and n.metadata->>'plan_entry_verification_id'=new.verification_id::text and not coalesce(n.is_archived,false));
  else
    update public.notifications set is_archived=true,metadata=metadata||jsonb_build_object('resolved',true)
      where metadata->>'plan_entry_verification_id'=new.verification_id::text and not coalesce(is_archived,false);
  end if;
  return null;
end;
$$;
revoke all on function insurance_internal.plan_review_alert() from public,anon,authenticated;

